/*
 * dsky.c -- pinball decimal display against the real AGC code (yaAGC).
 *
 * Inputs and expected words: tools/oracle/cases/dsky.spec / .txt
 * (Comanche055) and dsky_lm.spec / .txt (Luminary099), generated by
 * tools/oracle/cases/gen/gen_dsky.py. Every run is an internal NVSUB:
 * "V06 Nnn" (DECDSP through every SF output routine of SFOUTABR, DSPDECWD,
 * DSPDC2NR, HMSOUT, M/SOUT, 2INTOUT, DSPDECVN) or a verb paste (noun 0,
 * UPDATVB -> DSPDECVN). The noun's erasables are written through the
 * noun data layer (agc_noun_write) or, for the machine-address nouns
 * 01-03, the ECADR image; the eleven DSPTAB words, NOUT, VERBREG and
 * NOUNREG are compared bit-exact.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "../../src/io/dsky/pinball/internal.h"
#include "agc/core/assert.h"
#include "agc/core/state.h"
#include "agc/exec/exec.h"
#include "agc/io/dsky.h"
#include "agc/io/nouns.h"
#include "oracle_txt.h"

bool agc_assert_report(const char *file, int line, const char *expr)
{
    (void) printf("assert %s:%d %s\n", file, line, expr);

    return (false);
}

/* AGC erasable (spec name, word index) of each component of a noun. */
typedef struct dsky_noun
{
    uint8_t     noun;
    const char *name[3];
    int         idx[3];
} dsky_noun_t;

static const dsky_noun_t k_cm[] = {
    {33, {"TIG", NULL, NULL}, {0, 0, 0}},
    {40, {"TTOGO", "VGDISP", "DVTOTAL"}, {0, 0, 0}},
    {43, {"LAT", "LONG", "ALT"}, {0, 0, 0}},
    {45, {"VHFCNT", "TTOGO", "E7,1625"}, {0, 0, 0}},
    {47, {"CSMMASS", "LEMMASS", NULL}, {0, 0, 0}},
    {48, {"PACTOFF", "YACTOFF", NULL}, {0, 0, 0}},
    {21, {"PIPAX", "PIPAY", "PIPAZ"}, {0, 0, 0}},
    {20, {"CDUX", "CDUY", "CDUZ"}, {0, 0, 0}},
    {91, {"CDUS", "CDUT", NULL}, {0, 0, 0}},
    {64, {"D", "VMAGI", "RTGO"}, {0, 0, 0}},
    {88, {"STARSAV3", "STARSAV3", "STARSAV3"}, {0, 2, 4}},
    {54, {"RANGE", "RRATE", "RTHETA"}, {0, 0, 0}},
};

static const dsky_noun_t k_lm[] = {
    {33, {"TIG", NULL, NULL}, {0, 0, 0}},
    {72, {"CDUT", "CDUS", NULL}, {0, 0, 0}},
    {63, {"ABVEL", "HDOTDISP", "HCALC1"}, {0, 0, 0}},
    {68, {"RANGEDSP", "TTFDISP", "DELTAH"}, {0, 0, 0}},
    {64, {"FUNNYDSP", "HDOTDISP", "HCALC"}, {0, 0, 0}},
    {47, {"LEMMASS", "CSMMASS", NULL}, {0, 0, 0}},
};

#define DSKY_MCTBS_NAME "E7,1700"

static const dsky_noun_t *find_noun(bool lm, int noun)
{
    const dsky_noun_t *t = lm ? k_lm : k_cm;
    const size_t       n =
        lm ? sizeof k_lm / sizeof k_lm[0] : sizeof k_cm / sizeof k_cm[0];

    for (size_t i = 0; i < n; i++)
    {
        if (t[i].noun == noun)
        {
            return (&t[i]);
        }
    }

    return (NULL);
}

static agc_status_t write_comp(const char *t, uint16_t id,
                               const agc_scale_info_t *si, const char *name,
                               int idx)
{
    agc_dp_t v;

    if (si->is_dp)
    {
        v = oracle_in_dp(t, name, idx);
    }
    else if (si->is_raw)
    {
        v = (agc_dp_t) oracle_in_raw(t, name, idx);
    }
    else
    {
        v = agc_dp_from_sp((agc_sp_t) oracle_in(t, name, idx));
    }

    if (id == (uint16_t) AGC_DATA_TIG)
    {
        agc_erase_set_tig(v); /* the noun layer refuses negative times */

        return (AGC_STATUS_OK);
    }

    if (id == (uint16_t) AGC_DATA_TTOGO)
    {
        agc_erase_set_ttogo(v);

        return (AGC_STATUS_OK);
    }

    agc_status_t st = agc_dsky_noun_write(id, v);

    return ((st == AGC_STATUS_NOT_FOUND) ? agc_noun_write(id, v) : st);
}

static void compare(const char *t)
{
    char name[16];

    if (getenv("ORACLE_VERBOSE") != NULL)
    { /* the C display words, for gen/dsky_show.py */
        (void) printf("CDSPTAB %s", t);

        for (int k = 0; k < PIN_DSPTAB_PANEL; k++)
        {
            (void) printf(" %05o", (unsigned) agc_erase_dsptab(k));
        }

        (void) printf("\n");
    }

    for (int k = 0; k < PIN_DSPTAB_PANEL; k++)
    {
        (void) snprintf(name, sizeof name, "DSPTAB+%d", k);
        (void) oracle_cmp(t, name, (long) agc_erase_dsptab(k),
                          (long) oracle_out_raw(t, name), 0);
    }

    (void) oracle_cmp(t, "NOUT", pin_st()->nout, oracle_out_sp(t, "NOUT"), 0);
    (void) oracle_cmp(t, "VERBREG", pin_st()->verbreg,
                      oracle_out_sp(t, "VERBREG"), 0);
    (void) oracle_cmp(t, "NOUNREG", pin_st()->nounreg,
                      oracle_out_sp(t, "NOUNREG"), 0);
}

static void one(const char *t, bool lm)
{
    const int    vnw   = oracle_in(t, "NVTEMP", 0);
    const int    verb  = (vnw >> 7) & 0177;
    const int    noun  = vnw & 0177;
    const bool   mctbs = noun >= 1 && noun <= 3;
    agc_status_t st    = AGC_STATUS_OK;

    oracle_require_ok(t, "ENDOFJOB");
    agc_state_init(lm ? AGC_VEHICLE_LM : AGC_VEHICLE_CSM);
    (void) agc_exec_init();
    (void) agc_waitlist_init();
    (void) agc_dsky_init();

    if (noun == 0)
    {
        st = agc_dsky_nvsub((uint8_t) verb, 0);
    }
    else if (mctbs)
    {
        for (int k = 0; k < 3; k++)
        {
            st = agc_erase_write_ecadr((uint16_t) (03700 + k),
                                       oracle_in_raw(t, DSKY_MCTBS_NAME, k));
        }

        st = agc_dsky_nvsub_mctbs((uint8_t) verb, (uint8_t) noun,
                                  (uint16_t) oracle_in(t, "MPAC+2", 0));
    }
    else
    {
        const dsky_noun_t *dn = find_noun(lm, noun);
        agc_noun_t         row;

        if (dn == NULL || agc_noun_lookup((uint8_t) noun, &row) != AGC_STATUS_OK)
        {
            (void) oracle_cmp(t, "noun table", 1, 0, 0);

            return;
        }

        for (int k = 0; k < (int) row.ncomp && st == AGC_STATUS_OK; k++)
        {
            agc_scale_info_t si;

            if (dn->name[k] == NULL)
            {
                continue; /* HMS: one DP time for the three registers */
            }

            st = agc_scale_info((agc_scale_t) row.scale_type[k], &si);

            if (st == AGC_STATUS_OK)
            {
                st = write_comp(t, row.data_id[k], &si, dn->name[k],
                                dn->idx[k]);
            }
        }

        (void) oracle_cmp(t, "noun write status", st, AGC_STATUS_OK, 0);
        st = agc_dsky_nvsub((uint8_t) verb, (uint8_t) noun);
    }

    (void) oracle_cmp(t, "nvsub status", st, AGC_STATUS_OK, 0);
    compare(t);
}

/* Every "run TAG" of the loaded spec. */
static void all_runs(bool lm)
{
    const char *p = oracle_spec;

    while ((p = strstr(p, "\nrun ")) != NULL)
    {
        char   tag[64];
        size_t n = strcspn(p + 5, "\n");

        if (n >= sizeof tag)
        {
            n = sizeof tag - 1;
        }

        (void) memcpy(tag, p + 5, n);
        tag[n] = '\0';
        one(tag, lm);
        p += 5;
    }
}

int main(void)
{
    if (!oracle_load("dsky"))
    {
        (void) printf("oracle_dsky: SKIP (case files not found)\n");

        return (0);
    }

    all_runs(false);

    if (oracle_load("dsky_lm"))
    {
        all_runs(true);
    }

    return (oracle_finish("oracle_dsky"));
}
